226	@layer base {
227	  html {
228	    @apply font-sans;
229	  }
230	  /* Gradient-aware portfolio background — bg-portfolio-bg only sets a flat
231	     background-color, but dark mode needs a background-image gradient too.
232	     `none` in light mode means only the flat color paints. */
233	  .bg-portfolio-page {
234	    background-color: var(--portfolio-bg);
235	    background-image: var(--portfolio-bg-gradient);
236	  }
237	
238	  /* Shared headline treatment for every big Redaction-35 title on the site
239	     (home page's "Hi, I'm Cody", blog post titles, case-study titles).
240	     font-size is plain CSS, not a Tailwind arbitrary value — Tailwind v4's
241	     arbitrary-value parser can't handle the commas inside clamp(), even
242	     backslash-escaped, and silently drops the whole class instead of
243	     erroring. clamp() scales the size smoothly from 64px on small screens
244	     up to 80px, rather than snapping at a single breakpoint the way the
245	     home page's old text-[56px] sm:text-[80px] did — the 3vw term hits the
246	     64px floor around a 533px-wide viewport and the 80px ceiling around
247	     1067px, transitioning linearly in between. */
248	  .portfolio-headline {
249	    font-family: var(--font-redaction);
250	    font-size: clamp(4rem, 3rem + 3vw, 5rem);
251	    line-height: 0.94;
252	    letter-spacing: -2.4px;
253	    color: var(--portfolio-ink);
254	  }
255	
256	  /* Inline `code` spans (MDX backtick syntax, e.g. blog posts and case
257	     studies referencing component/prop names like `Card`) — site-wide,
258	     not scoped to any one layout's prose wrapper, since both BlogLayout
259	     and ProjectLayout render MDX content that can contain inline code. */
260	  code {
261	    font-family: var(--font-mono);
262	    border-radius: 4px;
263	    padding: 4px;
264	    background-color: oklch(94.5% 0.044 73.9deg);
265	  }
266	
267	  .dark code {
268	    background-color: oklch(33.5% 0.0104 286deg);
269	  }
270	}
