1	/* Undercurrent case-study sandbox — scoped design tokens.
2	   This is a visual clone of the real Undercurrent design system (a separate
3	   React+MUI+Emotion repo), rebuilt from scratch for this one demo. These
4	   tokens intentionally mirror Undercurrent's real semantic token *names*
5	   (neutral bg/text/border/icon, plus highlight/success/warning/danger color
6	   groups) so this file stays easy to audit against the real system, but the
7	   values only cover what the 7 demo components actually use — this is not
8	   a general-purpose token system.
9	
10	   Only imported by the sandbox's root component, so these rules never
11	   affect any other page. */
12	
13	/* ─── Base typography ───────────────────────────────────────────────────
14	   The case-study article body (.article-body in ProjectLayout.astro) sets
15	   font-family: var(--font-plex-sans) on itself, which every element in the
16	   MDX content inherits by default — including this island, since it renders
17	   real DOM nodes inside that wrapper. Undercurrent's real components use
18	   Geist Sans, so it's set explicitly here rather than relying on whatever
19	   the surrounding page happens to inherit. Geist Mono (secondary/technical
20	   text) is set per-element where needed, same as the real design system. */
21	.uc-demo {
22	  font-family: var(--font-sans);
23	}
24	
25	/* Every demo component reads its colors from --uc-demo-active-*, which
26	   changes instantly the moment data-uc-variant flips (CSS custom
27	   properties aren't themselves animatable) — this is what makes the actual
28	   painted color properties glide instead of snapping when the swatch
29	   switches. Scoped to [data-uc-variant]'s own descendants specifically
30	   (the inner bordered frame holding the 7 demo components), not the outer
31	   .uc-demo wrapper — the swatch row also lives under .uc-demo but already
32	   has its own motion/react-driven transition, and applying both here too
33	   would fight over the same background-color/color properties. */
34	[data-uc-variant] :where(*) {
35	  transition:
36	    background-color 200ms ease-out,
37	    border-color 200ms ease-out,
38	    color 200ms ease-out;
39	}
40	
41	/* ─── Neutral tokens (dark is the default; .dark class matches this file's
42	   own scope the same way global.css's :root/.dark pair does) ───────────── */
43	.uc-demo {
44	  --uc-demo-neutral-bg-main: #262523;
45	  --uc-demo-neutral-bg-weak: #181716;
46	  --uc-demo-neutral-bg-strong: #ffffff;
47	  --uc-demo-neutral-text-main: #ffffff;
48	  --uc-demo-neutral-text-medium: #e6e5e4;
49	  --uc-demo-neutral-text-weak: #a7a49f;
50	  --uc-demo-neutral-text-strong: #181716;
51	  --uc-demo-neutral-border-weak: #43413d;
52	  --uc-demo-neutral-icon-weak: #a7a49f;
53	
54	  /* ─── Color groups (raw values, before the active-variant redirection) ── */
55	  --uc-demo-highlight-bg-main: #1c42a8;
56	  --uc-demo-highlight-bg-strong: #bad2fd;
57	  --uc-demo-highlight-border-weak: #2159d4;
58	  --uc-demo-highlight-border-main: #bad2fd;
59	  --uc-demo-highlight-border-medium: #6097f9;
60	  --uc-demo-highlight-text-main: #bad2fd;
61	  --uc-demo-highlight-text-weak: #1c42a8;
62	  --uc-demo-highlight-icon-main: #bad2fd;
63	
64	  --uc-demo-success-bg-main: #14532d;
65	  --uc-demo-success-bg-strong: #bbf7d0;
66	  --uc-demo-success-border-weak: #166534;
67	  --uc-demo-success-border-main: #86efac;
68	  --uc-demo-success-text-main: #86efac;
69	  --uc-demo-success-text-weak: #14532d;
70	  --uc-demo-success-icon-main: #86efac;
71	
72	  --uc-demo-warning-bg-main: #713f12;
73	  --uc-demo-warning-bg-strong: #fde047;
74	  --uc-demo-warning-border-weak: #854d0e;
75	  --uc-demo-warning-border-main: #fde047;
76	  --uc-demo-warning-text-main: #fde047;
77	  --uc-demo-warning-text-weak: #713f12;
78	  --uc-demo-warning-icon-main: #fde047;
79	
80	  --uc-demo-danger-bg-main: #7f1d1d;
