257	     studies referencing component/prop names like `Card`) — site-wide,
258	     not scoped to any one layout's prose wrapper, since both BlogLayout
259	     and ProjectLayout render MDX content that can contain inline code. */
260	  code {
261	    font-family: var(--font-mono);
262	    border-radius: 4px;
263	    padding: 4px;
264	    background-color: oklch(94.5% 0.044 73.9deg);
265	  }
266	
267	  .dark code {
268	    background-color: oklch(33.5% 0.0104 286deg);
269	  }
270	}
