272	/* Per-project icon/badge colors (index.astro, ProjectLayout.astro) come from
273	   MDX frontmatter and can optionally differ by theme — same --x-light/--x-dark
274	   -> --x resolution pattern as --portfolio-bg above, except these are set
275	   inline per-element (from content data) rather than globally in :root/.dark,
276	   so the resolution rule has to live here instead of alongside --portfolio-bg. */
277	[style*="--icon-color-light"] {
278	  --icon-color: var(--icon-color-light);
279	}
280	[style*="--badge-color-light"] {
281	  --badge-color: var(--badge-color-light);
282	}
283	.dark [style*="--icon-color-dark"] {
284	  --icon-color: var(--icon-color-dark);
285	}
286	.dark [style*="--badge-color-dark"] {
287	  --badge-color: var(--badge-color-dark);
288	}
289	
290	@media (prefers-reduced-motion: no-preference) {
291	  [data-animate] {
292	    opacity: 0;
293	  }
294	}
295	
296	/* Theme-toggle sweep, driven by the View Transitions API (see the click
297	   handler in Footer.astro). The browser snapshots the page before and after
298	   the .dark class toggles into ::view-transition-old(root) and
299	   ::view-transition-new(root); overriding the default cross-fade with a
300	   clip-path keyframe reveals the new-theme screenshot as an expanding line
301	   sweeping across, with the old screenshot sitting untouched underneath —
302	   so each side of the line is already showing its correct final theme. */
303	::view-transition-old(root),
304	::view-transition-new(root) {
305	  animation: none;
306	  mix-blend-mode: normal;
307	}
308	
309	::view-transition-old(root) {
310	  z-index: 1;
311	}
312	
313	::view-transition-new(root) {
314	  z-index: 2;
315	}
316	
317	[data-theme-sweep-direction="light"]::view-transition-new(root) {
318	  animation: theme-sweep-up 500ms ease-in-out forwards;
319	}
320	
321	[data-theme-sweep-direction="dark"]::view-transition-new(root) {
322	  animation: theme-sweep-down 500ms ease-in-out forwards;
323	}
324	
325	@keyframes theme-sweep-up {
326	  from {
327	    clip-path: inset(100% 0 0 0);
328	  }
329	  to {
330	    clip-path: inset(0 0 0 0);
331	  }
332	}
333	
334	@keyframes theme-sweep-down {
335	  from {
336	    clip-path: inset(0 0 100% 0);
337	  }
338	  to {
339	    clip-path: inset(0 0 0 0);
340	  }
341	}
