input.new_string:
/* ─── Primitives ──────────────────────────────────────────────────────────
   Raw palette values, theme-agnostic, no semantic meaning attached. Not
   registered in @theme above, so none of these generate Tailwind utility
   classes (e.g. there is no `bg-indigo-700`) — they only exist to be
   referenced by the semantic --portfolio-*/--brand-* tokens below, keeping
   a single deliberate layer between "the palette" and "what a component
   actually uses."

   Imported steps are hand-copied from Tailwind v4's own installed palette
   (node_modules/tailwindcss/theme.css) — copied as static values rather
   than imported at build time, so this tier stays a stable, curated
   subset rather than silently drifting if Tailwind is upgraded later.
   --brand-* primitives are bespoke: colors that don't land near any
   imported step (a warm cream background, this site's specific teal/muted
   tones), authored directly rather than forced onto an ill-fitting step. */
:root {
  --zinc-900: #18181b;
  --zinc-600: #52525c;
  --zinc-400: #9f9fa9;

  --teal-700: #00786f;
  --teal-400: #00d5be;

  --indigo-700: #432dd7;
  --indigo-400: #7c86ff;
  --purple-700: #8200db;
  --purple-400: #c27aff;
  --orange-700: #ca3500;
  --orange-400: #ff8904;
  --amber-800: #973c00;
  --amber-700: #bb4d00;
  --amber-400: #ffb900;
  --amber-300: #ffd230;
  --green-700: #008236;
  --green-400: #05df72;
  --fuchsia-700: #a800b7;
  --fuchsia-400: #ed6aff;

  /* Hover-variant steps: one step darker (light mode) / one step lighter
       (dark mode) than each category's base step above, per the file's
       existing "hover = adjacent shade, same hue" pattern. */
  --indigo-800: #3730a3;
  --indigo-300: #a5b4fc;
  --purple-800: #6b21a8;
  --purple-300: #d8b4fe;
  --orange-800: #9a3412;
  --orange-300: #fdba74;
  --amber-900: #713f12;
  --amber-500: #facc15;
  --teal-800: #115e59;
  --teal-300: #5eead4;
  --green-800: #166534;
  --green-300: #86efac;
  --fuchsia-800: #86198f;
  --fuchsia-300: #f0abfc;
  --amber-600: #92400e;
  --amber-200: #fcd34d;

  /* Bespoke — no imported step lands near this site's warm cream/near-black
       surfaces or its specific muted/teal tuning. */
  --brand-cream: #fff9f2;
  --brand-muted-light: #52525c; /* == --zinc-600, named for its semantic role */
  --brand-muted-dark: #9f9fa9; /* == --zinc-400, named for its semantic role */
  --brand-warm-tan: #ffe9cd; /* inline `code` background, light mode */
  --brand-cool-dark: #36363c; /* inline `code` background, dark mode */
  --brand-warm-white: #fffaf5; /* lightbox backdrop base, light mode */
  --brand-section-border-dark: #3c3c44; /* Figma dark-mode section stroke — bluer than zinc-700/800, kept exact */
}

