// sRGB hex -> OKLCH (inverse of the earlier oklch->srgb pipeline)
function hexToRgb(hex) {
  hex = hex.replace('#','');
  return [0,2,4].map(i => parseInt(hex.slice(i,i+2),16));
}
function srgbToLinear(c) {
  c/=255;
  return c<=0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4);
}
function rgbToOklch(rgb) {
  const [r,g,b] = rgb.map(srgbToLinear);
  const l = 0.4122214708*r + 0.5363325363*g + 0.0514459929*b;
  const m = 0.2119034982*r + 0.6806995451*g + 0.1073969566*b;
  const s = 0.0883024619*r + 0.2817188376*g + 0.6299787005*b;
  const l_ = Math.cbrt(l), m_ = Math.cbrt(m), s_ = Math.cbrt(s);
  const L = 0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_;
  const a = 1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_;
  const b2 = 0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_;
  const C = Math.sqrt(a*a+b2*b2);
  let H = Math.atan2(b2,a) * 180/Math.PI;
  if (H<0) H+=360;
  return [L*100, C, H];
}
const colors = {
  'brand-cream': '#fff9f2',
  'brand-warm-tan': '#ffe9cd',
  'brand-cool-dark': '#36363c',
  'brand-warm-white': '#fffaf5',
  'brand-section-border-dark': '#3c3c44',
  'gradient-stop-dark-top': '#242429',
  'gradient-stop-dark-bottom (zinc-900)': '#18181b',
};
for (const [name, hex] of Object.entries(colors)) {
  const [L,C,H] = rgbToOklch(hexToRgb(hex));
  console.log(name, hex, '-> oklch(' + L.toFixed(1) + '% ' + C.toFixed(3) + ' ' + H.toFixed(3) + ')');
}
"

